input.command:
$profile = "E:\project\海外仓\automation\.browser_profile"
# 1) 是否有 chrome/chromium 进程锁定该 profile
$procs = Get-CimInstance Win32_Process -Filter "Name='chrome.exe' OR Name='chromium.exe'" |
  Where-Object { $_.CommandLine -like "*$profile*" }
if ($procs) {
  "⚠️ 检测到占用该 profile 的浏览器进程,需先关闭:"
  $procs | Select-Object ProcessId, CommandLine | Format-List
} else {
  "✅ 无进程占用该 profile,可安全清理。"
}
# 2) 清理前体积
"清理前 .browser_profile 大小: {0:N1} MB" -f ((Get-ChildItem $profile -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum/1MB)

$d = "E:\project\海外仓\automation\.browser_profile\Default"
"=== 登录态关键文件(应仍存在)==="
@("Cookies","Login Data","Web Data","Network","Local Storage","Session Storage","Local State") | ForEach-Object {
  $path = if ($_ -eq "Local State") { "E:\project\海外仓\automation\.browser_profile\$_" } else { "$d\$_" }
  $exists = Test-Path $path
  "{0,-18} {1}" -f $_, $(if ($exists) { "✅ 在" } else { "❌ 缺失" })
}

$net = "E:\project\海外仓\automation\.browser_profile\Default\Network"
if (Test-Path "$net\Cookies") {
  $c = Get-Item "$net\Cookies"
  "✅ Cookies 在 Default\Network\Cookies — {0:N0} KB, 修改于 {1}" -f ($c.Length/1KB), $c.LastWriteTime
} else { "❌ 未找到 Cookies 文件" }

$path = "E:\project\海外仓\automation\clear_cache.ps1"
$bytes = [System.IO.File]::ReadAllBytes($path)
$bom = [byte[]]@(0xEF,0xBB,0xBF)
if (-not ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)) {
    [System.IO.File]::WriteAllBytes($path, ($bom + $bytes))
    "已补 UTF-8 BOM"
} else { "已有 BOM" }
# 语法检查:确保脚本可解析
$null = [System.Management.Automation.PSParser]::Tokenize((Get-Content $path -Raw), [ref]$null)
"语法解析 OK"
